        /** The person as they stood then, unsaved. */
        public Person rebuild(String sheetId) {
            Person person = new Person(sheetId, name, grades.get(0).grade());
            grades.stream().skip(1).forEach(g -> person.setGradeFrom(g.from(), g.grade()));
            person.setTerms(terms);
            person.setRetiredFrom(retiredFrom);
            holds.forEach(h -> person.addHold(new Hold(h.from(), h.to())));
            return person;
        }
    }

    public record ClaimState(long id, long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
            String corrects, long listed, ClaimStatus status, String number, BigDecimal settledDue, boolean stated,
            BigDecimal statedDue, LocalDate deferredUntil, LocalDate remindedOn, String ref) {

        /** The claim as it stood then, unsaved. */
        public Claim rebuild(String sheetId) {
            Claim claim = new Claim(sheetId, personId, amount, date, dueBy, note, corrects, listed);
            claim.setStatus(status);
            claim.setNumber(number);
            claim.setSettledDue(settledDue);
            claim.setDeferredUntil(deferredUntil);
            claim.remind(remindedOn);
            claim.setRef(ref);
            if (stated) {
                claim.bind(statedDue);
            }
            return claim;
        }
    }

    /** What the sheet holds now. */
    public static SheetState of(Sheet sheet, List<Rate> rates, List<Person> people, List<Claim> claims, Views views) {
        return new SheetState(
                sheet.getSettings().stream().map(s -> new SettingState(s.getKey(), s.getFrom(), s.getValue())).toList(),
                sheet.getPolicyDate(),
                rates.stream().map(r -> new RateState(r.getGrade(), r.getFromDate(), r.getToDate(), r.getRate())).toList(),
                people.stream().map(SheetState::stateOf).toList(),
                claims.stream().map(c -> new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(),
                        c.getDueBy(), c.getNote(), c.getCorrects(), c.getListed(), c.getStatus(), c.getNumber(),
                        c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getDeferredUntil(), c.getRemindedOn(), c.getRef())).toList(),
                new TreeMap<>(sheet.getPermissions()), sheet.getPeriodNumberingFrom(), sheet.getGraceDays(),
                sheet.isArchived(), views, sheet.getEntryDate());
    }

    /** The people as the screen read them then, each with the grade in force on {@code today}. */
    public List<PersonView> people(String sheetId, LocalDate today) {
        return views.people().stream().map(v -> person(v.id())
                .map(p -> new PersonView(v.id(), v.name(), p.rebuild(sheetId).gradeOn(today), v.grades(), v.terms(),
                        v.version(), v.retired(), v.retiredFrom(), v.held(), v.holds()))
    /** The sheet as it stood at the end of a date; empty when no change was made on it by then. */
    @Transactional(readOnly = true)
    public Optional<SheetState> asOf(String sheetId, LocalDate date) {
        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByAsOfDescIdDesc(sheetId, date)
                .map(s -> json.readValue(s.getState(), SheetState.class));
    }

    /** The claim as kept: no one's editor lock is part of what the sheet held. */
    private static ClaimView unlocked(ClaimView c) {
        return new ClaimView(c.id(), c.personId(), c.amount(), c.date(), c.note(), c.status(), c.number(),
                c.settledDue(), c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(),
                c.log(), c.proofs(), c.splitFrom(), null, c.lateEntry(), c.remindedOn(), c.ref());
    }

    /** The lists the screen reads of the sheet as it stood at the end of a date; none when no change was made on it
     *  by then. */
    /** A claim split in two: the original, keeping the rest of its amount, and the new claim split off it. */
    public record Split(Claim original, Claim split) {
    }

    /** Split an amount (more than 0.00 and less than its amount) off an OPEN claim: it keeps the rest and loses any
     *  figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the same date
     *  and note, the next number, opened by this user, a due-by fixed now from the terms in force on the date and
     *  naming the original as the claim it was split from, is listed as the person's newest; it is a late entry when
     *  the original is, and is numbered within the period of its own due-by. Refused for a claim
     *  that is not OPEN or is deferred, one due by inside a closed period, an amount out of range, and a role the
